// SetSaftImportMatches records the customers' matches at once.
func (q *Queries) SetSaftImportMatches(ctx context.Context, arg SetSaftImportMatchesParams) error {
	_, err := q.db.Exec(ctx, setSaftImportMatches,
		arg.ImportID,
		arg.Positions,
		arg.Matches,
		arg.CustomerIds,
		arg.CustomerNames,
		arg.CustomerOrgs,
	)
	return err
}
